<script setup lang="ts">
import { ref } from 'vue';import { ElMessage } from 'element-plus';import { http, type ApiResponse } from '../api/http'
interface AuditLog{id:number;moduleCode:string;businessType:string;businessId:string;actionType:string;operatorName:string;beforeData:string|null;afterData:string|null;clientIp:string;operatedAt:string}
const rows=ref<AuditLog[]>([]),loading=ref(false),businessType=ref(''),businessId=ref(''),detail=ref(false),current=ref<AuditLog|null>(null),fmt=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false});const pretty=(v:string|null)=>{if(!v)return '—';try{return JSON.stringify(JSON.parse(v),null,2)}catch{return v}};const load=async()=>{loading.value=true;try{rows.value=(await http.get<ApiResponse<AuditLog[]>>('/system/audit-logs',{params:{businessType:businessType.value||undefined,businessId:businessId.value||undefined}})).data.data}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}finally{loading.value=false}};const open=(r:AuditLog)=>{current.value=r;detail.value=true};load()
</script>
<template><section class="page-card"><div class="page-heading"><div><h2>审计日志</h2><p>追溯关键业务变更的操作人、客户端地址及变更前后内容。</p></div></div><div class="filter-bar"><el-input v-model="businessType" clearable placeholder="业务类型" style="width:240px" @keyup.enter="load"/><el-input v-model="businessId" clearable placeholder="业务 ID" style="width:180px" @keyup.enter="load"/><el-button type="primary" :loading="loading" @click="load">查询</el-button><el-button @click="businessType='';businessId='';load()">重置</el-button></div><el-table v-loading="loading" :data="rows" stripe><el-table-column label="时间" width="180"><template #default="s">{{fmt(s.row.operatedAt)}}</template></el-table-column><el-table-column prop="moduleCode" label="模块" width="110"/><el-table-column prop="businessType" label="业务类型" min-width="140"/><el-table-column prop="businessId" label="业务 ID" width="110"/><el-table-column prop="actionType" label="动作" min-width="150"/><el-table-column prop="operatorName" label="操作人" width="110"/><el-table-column prop="clientIp" label="客户端 IP" width="140"/><el-table-column label="详情" width="80"><template #default="s"><el-button link type="primary" @click="open(s.row)">查看</el-button></template></el-table-column></el-table><el-dialog v-model="detail" title="变更详情" width="70%"><div class="audit-detail"><div><h4>变更前</h4><pre>{{pretty(current?.beforeData||null)}}</pre></div><div><h4>变更后</h4><pre>{{pretty(current?.afterData||null)}}</pre></div></div></el-dialog></section></template>
